#!/bin/sh
# The repo's deterministic checks. factory/bin/gate runs the main checkout's copy of
# this file inside a job's worktree; exit 0 means the gate passes.
# Generated by Eminzo from the files found in the repo: review it.
#
# Java/Kotlin (Gradle): `./gradlew test`, the repo's wrapper. No lint runs here: use
# `./gradlew check` instead if the repo wires lint into it (`check` includes `test`).
# Without a gradlew in the repo the generator writes `gradle` in its place.
# FACTORY_CHECK_MODE is "focused" while a builder iterates and "full" for the gate and the merge;
# in focused mode FACTORY_CHANGED_FILES names a file that lists the changed paths, one repo-relative
# path per line. A source file cannot be mapped to its tests, so a focused run narrows only when
# every changed path is a unit test class (*Test.java|kt, *Tests.java|kt); anything else runs
# everything. The full run below is the backstop.
set -e
MODE="${FACTORY_CHECK_MODE:-full}"
CHANGED="${FACTORY_CHANGED_FILES:-}"
# Read once, then unset, so a test that starts another factory process does not inherit them.
unset FACTORY_CHECK_MODE FACTORY_CHANGED_FILES

if [ "$MODE" = focused ] && [ -n "$CHANGED" ] && [ -s "$CHANGED" ]; then
  rc=0
  grep -qvE '(Test|Tests)\.(java|kt)$' "$CHANGED" || rc=$?
  if [ "$rc" -eq 1 ]; then
    # Only test classes changed: run those that still exist. No selection falls through.
    set --
    while IFS= read -r f; do
      if [ -e "$f" ]; then set -- "$@" --tests "*$(basename "$(basename "$f" .java)" .kt)"; fi
    done < "$CHANGED"
    if [ "$#" -gt 0 ]; then exec ./gradlew test "$@"; fi
  fi
fi

./gradlew test
